function restoreMissingPurchaseSuppliersFromKnownBackup(){
  if(configured||!Array.isArray(purchases)||!KNOWN_PURCHASE_SUPPLIERS.length)return false;
  const byId=new Map(KNOWN_PURCHASE_SUPPLIERS.filter(x=>x.id&&x.supplier).map(x=>[x.id,x.supplier]));
  const bySig=new Map();
  for(const x of KNOWN_PURCHASE_SUPPLIERS){
    const sig=[x.productId,x.batch,x.invoice,x.date,String(x.qty??'')].join('|');
    if(x.productId&&x.batch&&x.date)bySig.set(sig,x.supplier);
  }
  let changed=false;
  for(const p of purchases){
    if(String(p?.supplier||p?.supplierName||'').trim())continue;
    let supplier=byId.get(String(p?.id||''))||'';
    if(!supplier){
      const sig=[String(p?.productId||''),String(p?.batchNumber||p?.batch||''),String(p?.invoice||p?.invoiceNo||''),String(p?.purchaseDate||'').slice(0,10),String(p?.qty??p?.quantity??'')].join('|');
      supplier=bySig.get(sig)||'';
    }
    if(supplier){p.supplier=supplier;changed=true;}
  }
  if(changed)set('purchases',purchases);
  return changed;
}

function repairLocalStockConsistency(){
  // V5.9.74 CANONICAL PURCHASE -> SALES -> REMAINING LEDGER
  const sm=Array.isArray(get('stockMovements',[]))?get('stockMovements',[]):[];
  const norm=v=>String(v??'').trim().toLowerCase().replace(/\s+/g,' ');
  const productById=new Map(products.map(p=>[String(p?.id||''),p]).filter(x=>x[0]));
  const batchById=new Map(batches.map(b=>[String(b?.id||''),b]).filter(x=>x[0]));
  const batchKey=(pid,bn)=>String(pid||'')+'__'+norm(bn);
  const batchByKey=new Map();
  for(const b of batches){const k=batchKey(b?.productId,b?.batchNumber||b?.batch);if(String(b?.productId||'')&&norm(b?.batchNumber||b?.batch)){if(!batchByKey.has(k))batchByKey.set(k,[]);batchByKey.get(k).push(b)}}
  const resolveProduct=(id,name)=>{const p=productById.get(String(id||''));if(p)return p;const n=norm(name),arr=products.filter(x=>norm(x?.name)===n);return arr.length===1?arr[0]:null};
  const resolveBatch=(prod,bn,bid)=>{const byId=batchById.get(String(bid||'')),wanted=norm(bn);if(byId&&String(byId.productId||'')===String(prod?.id||'')&&(!wanted||norm(byId.batchNumber||byId.batch)===wanted))return byId;if(!wanted)return null;const arr=batchByKey.get(batchKey(prod?.id,wanted))||[];return arr.length===1?arr[0]:null};
  const purchaseQtyByBatch=new Map();
  for(const pu of purchases){const q=Math.max(0,Number(pu?.qty??pu?.quantity??0));if(!q)continue;const prod=resolveProduct(pu?.productId||pu?.productID,pu?.productName||pu?.medicine||pu?.name);if(!prod)continue;const b=resolveBatch(prod,pu?.batchNumber||pu?.batch,pu?.batchId||'');if(!b)continue;const bid=String(b.id);purchaseQtyByBatch.set(bid,(purchaseQtyByBatch.get(bid)||0)+q)}
  const saleQtyByBatch=new Map(),seenBills=new Set();
  for(const bill of bills){const billId=String(bill?.id||'');if(!billId||seenBills.has(billId)||bill?.returned)continue;seenBills.add(billId);for(const it of (bill?.items||[])){const q=Math.max(0,Number(it?.qty??it?.quantity??0));if(!q)continue;const prod=resolveProduct(it?.productId,it?.name||it?.productName||it?.medicine);if(!prod)continue;const b=resolveBatch(prod,it?.batchNumber||it?.batch,it?.batchId||'');if(!b)continue;const bid=String(b.id);saleQtyByBatch.set(bid,(saleQtyByBatch.get(bid)||0)+q)}}
  const adjustmentByBatch=new Map();
  for(const m of sm){const type=String(m?.type||'').toUpperCase();if(type!=='STOCK_ADJUSTMENT'&&type!=='ADJUSTMENT')continue;const prod=resolveProduct(m?.productId,m?.productName||m?.medicine);if(!prod)continue;const b=resolveBatch(prod,m?.batchNumber||m?.batch,m?.batchId||'');if(!b)continue;const bid=String(b.id);adjustmentByBatch.set(bid,(adjustmentByBatch.get(bid)||0)+Number(m?.qty||0))}
  const stockByProduct=new Map();
  for(const b of batches){const bid=String(b?.id||'');if(!bid)continue;let stock;if(purchaseQtyByBatch.has(bid)){const opening=(b?.openingStockSource==='MANUAL'||b?.openingStockSource==='OPENING_STOCK')?Math.max(0,Number(b?.openingStock||0)):0;stock=Math.max(0,opening+Number(purchaseQtyByBatch.get(bid)||0)-Number(saleQtyByBatch.get(bid)||0)+Number(adjustmentByBatch.get(bid)||0));b.stock=stock}else{stock=Math.max(0,Number(b?.stock||0))}const pid=String(b?.productId||'');if(pid)stockByProduct.set(pid,(stockByProduct.get(pid)||0)+stock)}
  for(const p of products){const pid=String(p?.id||'');if(!pid)continue;const hasBatch=batches.some(b=>String(b?.productId||'')===pid);p.stock=hasBatch?Math.max(0,Number(stockByProduct.get(pid)||0)):Math.max(0,Number(p?.stock||0))}
  set('batches',batches);set('products',products);localStorage.setItem('skm_stock_reconciled_v12','yes');
}

const VERIFIED_SNAPSHOT_B64='';
function decodeVerifiedSnapshot(){
  const bin=atob(VERIFIED_SNAPSHOT_B64),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
  return new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text().then(JSON.parse);
}
async function migrateVerifiedSnapshotOnce(){
  if(configured||localStorage.getItem('skm_verified_snapshot_migrated_v2')==='yes')return false;
  const data=await decodeVerifiedSnapshot(),c=data?.collections||{};
  const mergeBaseline=(current,baseline)=>{const cur=Array.isArray(current)?current:[],base=Array.isArray(baseline)?baseline:[];const map=new Map();for(const x of base){const id=String(x?.id||'');if(id)map.set(id,x)}for(const x of cur){const id=String(x?.id||'');if(id&&!map.has(id))map.set(id,x)}return [...map.values()]};
  products=mergeBaseline(get('products',[]),c.products);
  purchases=mergeBaseline(get('purchases',[]),c.purchases).filter(x=>x?.recovered!==true);
  bills=mergeBaseline(get('bills',[]),c.bills);
  // Do NOT retain legacy synthetic batches merely because they exist in localStorage.
  // Keep verified snapshot batches plus only genuinely newer local batches that have
  // an explicit purchase entry or explicit manual opening stock. This is what removes
  // the old 2675-batch inflation without deleting real new stock.
  const baselineBatchIds=new Set((c.batches||[]).map(x=>String(x?.id||'')).filter(Boolean));
  const localPurchases=get('purchases',[]).filter(x=>x?.recovered!==true);
  const localBatchIsLegitimate=b=>{
    const bid=String(b?.id||''),pid=String(b?.productId||''),bn=normMedicineName(b?.batchNumber||b?.batch);
    if(baselineBatchIds.has(bid))return true;
    if(b?.openingStockSource==='MANUAL'||b?.openingStockSource==='OPENING_STOCK')return true;
    return localPurchases.some(p=>String(p?.batchId||'')===bid || (String(p?.productId||'')===pid && bn && normMedicineName(p?.batchNumber||p?.batch)===bn));
  };
  const baselineBatches=Array.isArray(c.batches)?c.batches:[];
  const localBatches=get('batches',[]).filter(localBatchIsLegitimate);
  const batchMap=new Map(baselineBatches.map(x=>[String(x?.id||''),x]).filter(x=>x[0]));
  for(const b of localBatches){const id=String(b?.id||'');if(id&&!batchMap.has(id))batchMap.set(id,b)}
  batches=[...batchMap.values()];
  customers=mergeBaseline(get('customers',[]),c.customers);
  suppliers=mergeBaseline(get('suppliers',[]),c.suppliers);
  currentOrders=mergeBaseline(get('orders',[]),c.orders);
  reminders=mergeBaseline(loadLocalReminders(),c.reminders);
  const moves=mergeBaseline(get('stockMovements',[]),c.stockMovements);
  set('products',products);set('purchases',purchases);set('batches',batches);set('bills',bills);set('customers',customers);set('suppliers',suppliers);set('orders',currentOrders);persistReminders(reminders);set('stockMovements',moves);
  repairLocalStockConsistency();
  localStorage.setItem('skm_verified_snapshot_migrated_v2','yes');
  return true;
}

async function loadAll(force=false){
 recoverMissingLocalReminders();
 if(!configured){
   try{await migrateVerifiedSnapshotOnce()}catch(e){console.error('Verified snapshot migration failed:',e)}
   products=get('products',[]);currentOrders=get('orders',[]);purchases=get('purchases',[]);restoreMissingPurchaseSuppliersFromKnownBackup();batches=get('batches',[]);bills=get('bills',[]);customers=get('customers',[]);reminders=loadLocalReminders();suppliers=get('suppliers',[]);
   renderAll();return
 }
 if(liveStarted&&!force){renderAll();schedulePendingBillSync();return}
 if(force){location.reload();return}
 if(!db)await ensureFirebase();
 // Preserve existing local records before Firebase listeners start. A cloud snapshot must not make locally saved products disappear.
 products=get('products',products).filter(x=>!getDeletedProducts().has(String(x.id)));currentOrders=get('orders',currentOrders);purchases=get('purchases',purchases);batches=get('batches',batches);bills=get('bills',bills);customers=get('customers',customers);reminders=get('reminders',reminders);suppliers=get('suppliers',suppliers);
 liveStarted=true;
 const mergeRemoteKeepLocal=(localRows,remoteRows)=>{const map=new Map((localRows||[]).map(x=>[String(x?.id||''),x]));for(const x of (remoteRows||[])){const id=String(x?.id||'');if(id)map.set(id,x)}return [...map.values()]};
 const listen=(name,assign)=>onSnapshot(collection(db,name),s=>{const rows=s.docs.map(d=>({id:d.id,...d.data()}));if(name==='products'){const deleted=getDeletedProducts();assign(rows.filter(x=>!deleted.has(String(x.id))))}else assign(rows);if(name==='bills')bills=mergePendingBills(bills);if(name==='products'||name==='batches')applyPendingStockOverlay();renderAll();schedulePendingBillSync()},e=>{console.error('Firebase '+name+' error:',e);const n=$('notice');if(n)n.innerHTML='<b>⚠️ Firebase '+esc(name)+' sync issue</b><br><span class="small">Billing remains available; local changes are retained and will retry automatically.</span>'});
 listen('orders',v=>currentOrders=v.sort((a,b)=>t(b.createdAt)-t(a.createdAt)));
 listen('products',v=>{products=mergeRemoteKeepLocal(products,v);set('products',products);applyPendingStockOverlay()});
 listen('purchases',v=>{purchases=mergePendingPurchases(mergeRemoteKeepLocal(purchases,v));set('purchases',purchases);schedulePendingPurchaseSync()});
 listen('batches',v=>{batches=mergeRemoteKeepLocal(batches,v);set('batches',batches);applyPendingStockOverlay()});
 listen('bills',v=>{bills=mergePendingBills(v)});
 listen('customers',v=>customers=v);
 listen('reminders',v=>reminders=v.sort((a,b)=>t(a.reminderDate)-t(b.reminderDate)));
 listen('suppliers',v=>suppliers=v);
 schedulePendingBillSync();schedulePendingPurchaseSync();
} window.loadAll=loadAll;
function loadPurchaseHeaderDefaults(){
  const d=get('purchaseHeaderDefaults',{});
  if($('puDate')&&!$('puDate').value)$('puDate').value=d.date||today();
  if($('puSupplier')&&!$('puSupplier').value)$('puSupplier').value=String(d.supplier||'');
  if($('puInvoice')&&!$('puInvoice').value)$('puInvoice').value=String(d.invoice||'');
}
function savePurchaseHeaderDefaults(){
  if(editingPurchaseId)return;
  set('purchaseHeaderDefaults',{date:$('puDate')?.value||today(),supplier:$('puSupplier')?.value?.trim()||'',invoice:$('puInvoice')?.value?.trim()||''});
}
function bindPurchaseHeaderDefaults(){
  ['puDate','puSupplier','puInvoice'].forEach(id=>{const el=$(id);if(!el||el.dataset.headerBound==='1')return;el.dataset.headerBound='1';el.addEventListener('change',savePurchaseHeaderDefaults);el.addEventListener('input',savePurchaseHeaderDefaults);});
  loadPurchaseHeaderDefaults();
}
function renderAll(){
  // Reuse stock calculations during one render cycle; this avoids repeatedly scanning
  // hundreds of products/batches on mobile and keeps the UI responsive.
  effectiveStockCache=new Map();
  rebuildEffectiveStockCache();
  if($('puDate')&&!$('puDate').value)$('puDate').value=today();
  renderDashboard();
  renderSelects();
  const active=document.querySelector('.view:not(.hidden)')?.id||'home';
  if(active==='home')renderMedicineCheck();
  else if(active==='billing')renderBilling();
  else if(active==='purchase'){renderPurchases();renderBatches();}
  else if(active==='stock')renderStock();
  else if(active==='history')renderBillHistory();
  else if(active==='reports'){renderReports();renderScheduleList();}
  else if(active==='orders')renderOrders();
  else if(active==='reminders')renderReminders();
  else if(active==='suppliers')renderSuppliers();
  else if(active==='settings'){};
}
function renderMedicineCheck(){
 const r=$('mcResult'); if(!r)return;
 if(!r.dataset.initialized) r.innerHTML='<div class="small">Search any medicine to check availability.</div>';
 r.dataset.initialized='1';
}
window.checkMedicineAvailability=()=>{
 const input=$('mcSearch'); const result=$('mcResult'); if(!input||!result)return;
 const q=input.value.trim(); if(!q){result.innerHTML='<div class="warning">Enter a medicine name.</div>';return}
 const nq=normMedicineName(q);
 const exactProducts=products.filter(p=>normMedicineName(p.name)===nq);
 const list=exactProducts.length?exactProducts:medicineMatches(q);
 if(!list.length){result.innerHTML='<div class="zero"><b>❌ Medicine not found</b><br><span class="small">No matching medicine is in the current stock list.</span></div>';return}
 const groups=new Map();
 list.forEach(p=>{const key=normMedicineName(p.name)||String(p.id);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p)});
 result.innerHTML=[...groups.values()].map(group=>{
   const representative=group[0];
   const ids=new Set(group.map(p=>String(p.id)));
   const name=normMedicineName(representative.name);
   // Resolve batches by product id/name AND legacy purchase records. Older
   // imports can leave a batch with a different productId or slightly different
   // name formatting, even though the purchase clearly belongs to this medicine.
   const matchingPurchases=(purchases||[]).filter(pu=>{
     const puName=normMedicineName(pu?.productName||pu?.medicine||pu?.name);
     const puPid=String(pu?.productId||'');
     return (puPid&&ids.has(puPid)) || (!!name&&puName===name);
   });
   const purchasePids=new Set(matchingPurchases.map(pu=>String(pu?.productId||'')).filter(Boolean));
   const purchaseBatches=new Set(matchingPurchases.map(pu=>normMedicineName(pu?.batchNumber||pu?.batch)).filter(Boolean));
   const relatedBatches=batches.filter(b=>{
     if(ids.has(String(b.productId??''))||purchasePids.has(String(b.productId??'')))return true;
     const batchNames=[b?.productName,b?.medicineName,b?.medicine,b?.name].map(normMedicineName).filter(Boolean);
     if(!!name&&batchNames.includes(name))return true;
     const bn=normMedicineName(b?.batchNumber||b?.batch);
     return !!bn&&purchaseBatches.has(bn);
   });
   const usable=relatedBatches.filter(b=>Number(b.stock||0)>0&&expiryStatus(b)!=='EXPIRED');
   const qty=usable.reduce((sum,b)=>sum+Math.max(0,Number(b.stock||0)),0);
   const productQty=group.reduce((sum,p)=>sum+Math.max(0,Number(p.stock||0)),0);
   const effectiveQty=relatedBatches.length?qty:productQty;
   const near=usable.filter(b=>expiryStatus(b)==='NEAR EXPIRY').length;
   const status=effectiveQty>0?'Available':'Out of Stock';
   const statusGood=effectiveQty>0;
   const batchText=usable.length?usable.sort((a,b)=>t(a.expiryDate)-t(b.expiryDate)).map(b=>'<div class="small">Batch '+esc(b.batchNumber||'-')+' • Exp '+esc(b.expiryDate||'-')+' • Stock '+Number(b.stock||0)+'</div>').join(''):'<div class="small">'+(productQty>0?'Product stock is '+productQty+' but no matching saleable batch was found.':'No saleable batch stock available.')+'</div>';
   return '<div class="'+(statusGood?'good':'zero')+'"><b>'+esc(representative.name||'Medicine')+'</b><span class="pill '+(statusGood?'':'bad')+'">'+status+(statusGood?' ✅':' ❌')+'</span><div style="margin-top:8px"><b>Current available stock: '+effectiveQty+'</b>'+(qty===0&&productQty>0?'<br><span class="small">⚠️ Product stock and batch stock are not linked correctly.</span>':'')+(near?'<br><span class="small">⚠️ '+near+' batch(es) near expiry</span>':'')+'</div><div style="margin-top:8px">'+batchText+'</div></div>';
 }).join('');
};

function expiryStatus(b){const x=t(b.expiryDate),now=Date.now(),soon=now+30*864e5;return !x?'NO EXPIRY':x<now?'EXPIRED':x<=soon?'NEAR EXPIRY':'OK'}
function renderDashboard(){const low=products.filter(p=>effectiveMedicineStock(p)<=Number(p.lowStockLevel??10)),zero=products.filter(p=>effectiveMedicineStock(p)<=0),exp=batches.filter(b=>['EXPIRED','NEAR EXPIRY'].includes(expiryStatus(b)));const sales=bills.filter(b=>!b.returned&&String(b.billDate||'')===today()).reduce((s,b)=>s+Number(b.grandTotal||0),0);$('lowCount').textContent=low.length;$('expiryCount').textContent=exp.length;$('salesCount').textContent=money(sales);const bc=$('batchCount');if(bc){const keys=new Set(batches.map(b=>String(b?.productId||'')+'|'+String(b?.batchNumber||b?.batch||'').trim().toUpperCase()).filter(x=>!x.startsWith('|')));bc.textContent=keys.size;}const effectiveStockById=new Map(products.map(p=>[String(p.id),Math.max(0,effectiveMedicineStock(p))]));const zeroAlerts=zero;const lowAlerts=low.filter(p=>!zeroAlerts.includes(p));const catKey=p=>{const raw=String(p?.cat||p?.category||'Human Medicines').trim();const l=raw.toLowerCase();if(l.includes('veterinary'))return 'Veterinary';if(l.includes('human'))return 'Human Medicines';if(l.includes('baby'))return 'Baby Care';if(l.includes('pet'))return 'Pet Products';if(l.includes('health'))return 'Health';if(l.includes('device'))return 'Devices';if(l.includes('cosmetic'))return 'Cosmetics';return raw||'Other';};const catLabel={"Human Medicines":"💊 HUMAN MEDICINES","Veterinary":"🐾 VETERINARY MEDICINES","Baby Care":"👶 BABY PRODUCTS","Pet Products":"🐶 PET PRODUCTS","Health":"🩺 HEALTH CARE","Devices":"🩹 MEDICAL DEVICES","Cosmetics":"💄 COSMETICS",Other:"📦 OTHER"};const groups={};[...zeroAlerts.map(p=>({...p,__kind:'OUT OF STOCK'})),...lowAlerts.map(p=>({...p,__kind:'LOW STOCK'}))].forEach(p=>{const c=catKey(p);(groups[c]||(groups[c]=[])).push(p)});const alerts=[];Object.keys(groups).sort((a,b)=>{const order=['Human Medicines','Veterinary','Baby Care','Pet Products','Health','Devices','Cosmetics','Other'];return (order.indexOf(a)<0?99:order.indexOf(a))-(order.indexOf(b)<0?99:order.indexOf(b))}).forEach(c=>{alerts.push('<div style="font-weight:800;font-size:16px;margin:12px 0 6px">'+esc(catLabel[c]||c)+'</div>');groups[c].forEach(p=>{const effective=effectiveStockById.get(String(p.id))||0;alerts.push('<div class="warning">'+esc(p.__kind+': '+p.name+' ('+effective+')')+'</div>')})});exp.forEach(b=>alerts.push('<div class="warning">'+esc(expiryStatus(b)+': '+(b.productName||b.productId)+' • Batch '+(b.batchNumber||'-')+' • '+b.expiryDate)+'</div>'));$('alerts').innerHTML=alerts.join('')||'<div class="good">No urgent stock or expiry alerts.</div>';
$('recentBills').innerHTML=bills.slice(0,10).map(b=>billRow(b,true)).join('')||'<div class="small">No bills yet.</div>'}
function renderSelects(){
 const selected=$('bMedicine').value,selectedPu=$('puProduct').value;
 const billSearch=$('bMedicineSearch'),purchaseSearch=$('puProductSearch');
 const currentBill=products.find(p=>p.id===selected);
 const currentPurchase=products.find(p=>p.id===selectedPu);
 if(currentBill&&billSearch)billSearch.value=currentBill.name;
 if(currentPurchase&&purchaseSearch)purchaseSearch.value=currentPurchase.name;
 const dl=$('supplierOptions');
 if(dl)dl.innerHTML=suppliers.map(x=>'<option value="'+esc(x.name)+'">'+esc(x.mobile||'')+'</option>').join('');
 updateBatchOptions();
}
function normMedicineName(value){return String(value||'').trim().toLowerCase().replace(/\s+/g,' ');}
function batchMatchesProduct(b,p){
 const pid=String(p?.id??'');
 const name=normMedicineName(p?.name);
 if(String(b?.productId??'')===pid)return true;
 const batchNames=[b?.productName,b?.medicineName,b?.medicine,b?.name].map(normMedicineName).filter(Boolean);
 return !!name && batchNames.includes(name);
}
function batchesForProduct(p){
 return batches.filter(b=>batchMatchesProduct(b,p));
}
function effectiveMedicineStock(p){
 const pid=String(p?.id??'');
 if(!pid)return 0;
 if(effectiveStockCache.has(pid))return effectiveStockCache.get(pid);
 const related=batches.filter(b=>String(b?.productId??'')===pid);
 const total=related.reduce((n,b)=>n+Math.max(0,Number(b?.stock||0)),0);
 const value=related.length?total:Math.max(0,Number(p?.stock||0));
 effectiveStockCache.set(pid,value);return value;
}
function findMedicineBySearch(value){
 const q=String(value||'').trim().toLowerCase(); if(!q)return null;
 const exact=products.find(p=>String(p.name||'').trim().toLowerCase()===q); if(exact)return exact;
 const starts=products.filter(p=>String(p.name||'').trim().toLowerCase().startsWith(q)); if(starts.length===1)return starts[0];
 const contains=products.filter(p=>String(p.name||'').trim().toLowerCase().includes(q)); return contains.length===1?contains[0]:null;
}
function medicineMatches(q){
 q=String(q||'').trim().toLowerCase();
 if(!q)return products.slice(0,30);
 return products.filter(p=>String(p.name||'').toLowerCase().includes(q)).slice(0,30);
}
function showMedicineSuggestions(inputId,boxId,onPick){
 const input=$(inputId),box=$(boxId); if(!input||!box)return;
 const render=()=>{
   const list=medicineMatches(input.value);
   if(!list.length){box.innerHTML='<div class="medicineOption"><small>No medicine found</small></div>';box.classList.add('show');return}
   box.innerHTML=list.map(p=>{const available= inputId==='mcSearch' ? batchesForProduct(p).filter(b=>Number(b.stock||0)>0&&expiryStatus(b)!=='EXPIRED').reduce((sum,b)=>sum+Number(b.stock||0),0) : Number(p.stock||0);return '<div class="medicineOption" data-id="'+esc(p.id)+'"><b>'+esc(p.name)+'</b><small>Available stock: '+available+'</small></div>'}).join('');
   box.querySelectorAll('.medicineOption[data-id]').forEach(el=>el.addEventListener('pointerdown',e=>{
      e.preventDefault(); const p=products.find(x=>x.id===el.dataset.id); if(!p)return;
      input.value=p.name; box.classList.remove('show'); onPick(p);
   }));
   box.classList.add('show');
 };
 input.addEventListener('input',()=>{onPick(null);render()});
 input.addEventListener('focus',render);
 input.addEventListener('keydown',e=>{if(e.key==='Escape')box.classList.remove('show')});
 document.addEventListener('pointerdown',e=>{if(!box.contains(e.target)&&e.target!==input)box.classList.remove('show')});
 input.addEventListener('change',()=>{const p=findMedicineBySearch(input.value);if(p){onPick(p);input.value=p.name}else onPick(null)});
}
function pickBillMedicine(p){
 $('bMedicine').value=p?p.id:'';
 updateBatchOptions();
 if(p)$('bPrice').value=Number(p.price||0);
}
function pickPurchaseMedicine(p){
 $('puProduct').value=p?p.id:'';
 if($('puProductSearch'))$('puProductSearch').dataset.productFound=p?'yes':'no';
 if(p&&$('puCategory'))$('puCategory').value=p.cat||'Human Medicines';
 if($('puSchedule'))$('puSchedule').value=String(p?.schedule||'').toUpperCase().replace('SCHEDULE ','');
 if($('puMinQty'))$('puMinQty').value=Number(p?.lowStockLevel??10);
 if($('puManufacturer'))$('puManufacturer').value=p?.manufacturer||p?.manufacturerDetails||'';
}
function syncBillMedicine(){pickBillMedicine(findMedicineBySearch($('bMedicineSearch').value))}
function syncPurchaseMedicine(){pickPurchaseMedicine(findMedicineBySearch($('puProductSearch').value))}
showMedicineSuggestions('bMedicineSearch','bMedicineSuggest',pickBillMedicine);
showMedicineSuggestions('puProductSearch','puMedicineSuggest',pickPurchaseMedicine);
showMedicineSuggestions('mcSearch','mcSuggest',p=>{if(p){$('mcSearch').value=p.name;window.checkMedicineAvailability()}});
$('mcSearch')?.addEventListener('input',()=>{if($('mcSearch').value.trim())window.checkMedicineAvailability();else if($('mcResult'))$('mcResult').innerHTML='<div class="small">Search any medicine to check availability.</div>'});
window.updateBatchOptions=()=>{const pid=$('bMedicine').value;const bs=batches.filter(b=>b.productId===pid&&Number(b.stock||0)>0&&expiryStatus(b)!=='EXPIRED').sort((a,b)=>t(a.expiryDate)-t(b.expiryDate));$('bBatch').innerHTML='<option value="">Select batch</option>'+bs.map(b=>'<option value="'+esc(b.id)+'">'+esc(b.batchNumber)+' • Exp '+esc(b.expiryDate)+' • Stock '+Number(b.stock||0)+'</option>').join('')};$('bBatch').addEventListener('change',()=>{const b=batches.find(x=>x.id===$('bBatch').value);if(b)$('bPrice').value=Number(b.sellingPrice||products.find(p=>p.id===b.productId)?.price||0)});
window.addBillItem=()=>{if(!$('bMedicine').value){const typed=findMedicineBySearch($('bMedicineSearch').value);if(typed)pickBillMedicine(typed)}const pid=$('bMedicine').value,bid=$('bBatch').value,qty=Math.max(1,Number($('bQty').value)||1),price=Math.max(0,Number($('bPrice').value)||0);const p=products.find(x=>x.id===pid),b=batches.find(x=>x.id===bid);if(!p||!b)return alert('Select medicine and batch.');if(expiryStatus(b)==='EXPIRED')return alert('Expired batch cannot be billed.');const already=billCart.filter(x=>x.batchId===bid).reduce((s,x)=>s+x.qty,0);if(Number(b.stock||0)<already+qty)return alert('Insufficient batch stock.');billCart.push({productId:pid,name:p.name,batchId:bid,batchNumber:b.batchNumber,expiryDate:b.expiryDate,manufacturer:b.manufacturer||b.manufacturerDetails||p.manufacturer||p.manufacturerDetails||'',qty,price});renderBilling()};
/* Bill discount can be either a flat rupee amount or a percentage. */
window.setDiscountType=(type)=>{
  discountType=type==='percent'?'percent':'flat';
  const flat=$('discountFlatBtn'),percent=$('discountPercentBtn'),label=$('discountInputLabel'),input=$('bDiscount');
  if(flat)flat.classList.toggle('active',discountType==='flat');
  if(percent)percent.classList.toggle('active',discountType==='percent');
  if(label)label.textContent=discountType==='percent'?'Discount (%)':'Discount (₹)';
  if(input){input.placeholder=discountType==='percent'?'0 - 100':'0';input.max=discountType==='percent'?'100':'';}
  renderBilling();
};
window.setGstRate=()=>{const input=$('bGst');if(!input)return;const value=prompt('Enter GST %',input.value||'0');if(value===null)return;const rate=Math.max(0,Number(value)||0);input.value=rate;renderBilling()};
function billTotals(items=billCart){
 const sub=items.reduce((sum,x)=>sum+Number(x.qty||0)*Number(x.price||0),0);
 const discInput=$('bDiscount'),gstInput=$('bGst');
 const legacyDiscount=items.reduce((sum,x)=>sum+Number(x.discount||0),0);
 const rawDiscount=Math.max(0,discInput?Number(discInput.value||0):legacyDiscount);
 const discountRate=discountType==='percent'?Math.min(100,rawDiscount):0;
 const discount=discountType==='percent'
   ?Math.min(sub,sub*discountRate/100)
   :Math.min(sub,rawDiscount);
 const gstRate=Math.max(0,gstInput?Number(gstInput.value||0):0);
 const taxable=Math.max(0,sub-discount);
 const gst=taxable*gstRate/100;
 return {subtotal:sub,discount,discountType,discountInput:rawDiscount,discountRate,gst,gstRate,grandTotal:taxable+gst}
}
function renderBilling(){const pv=$('billPreview');if(pv)pv.textContent='SKM-'+today().replaceAll('-','')+'-NEW';const z=billTotals();$('bSub').textContent=money(z.subtotal);$('bDisc').textContent=money(z.discount);$('bTax').textContent=money(z.gst);$('bTotal').textContent=money(z.grandTotal);$('billItems').innerHTML=billCart.map((x,i)=>'<div class="itemrow"><b>'+esc(x.name)+'</b><br><span class="small">Batch '+esc(x.batchNumber)+' • '+x.qty+' × '+money(x.price)+' • Exp '+esc(x.expiryDate)+'</span><button class="danger" style="width:auto;float:right" onclick="removeBillItem('+i+')">Remove</button></div>').join('')||'<div class="small">No items added.</div>'} window.removeBillItem=i=>{billCart.splice(i,1);renderBilling()};
window.clearBill=()=>{billCart=[];sourceOrderId='';$('bCustomer').value='';$('bMobile').value='';$('bDoctor').value='';$('bNote').value='';$('bDiscount').value=0;$('bGst').value=0;window.setDiscountType('flat');renderBilling()};
/* Live billing total update when Discount ₹ or GST % changes */
window.recalculateBillTotals=()=>renderBilling();
['bDiscount','bGst'].forEach(id=>{const el=$(id);if(el){el.addEventListener('input',renderBilling);el.addEventListener('change',renderBilling);el.addEventListener('keyup',renderBilling);}});
window.saveBill=async()=>{
 const saveBtn=document.querySelector('#saveBillBtn');
 if(saveBtn?.dataset.saving==='1')return;
 if(!billCart.length)return alert('Add at least one item.');
 const totals=billTotals(),customerName=$('bCustomer').value.trim()||'Walk-in Customer',mobile=$('bMobile').value.trim(),doctor=$('bDoctor').value.trim(),paymentMode=$('bPayment').value,note=$('bNote').value.trim();
 const items=billCart.map(x=>({...x,qty:Math.max(1,Number(x.qty||0))}));
 const pending=getPendingBills();
 const usedInvoiceNumbers=new Set([...bills,...pending].map(b=>String(b?.invoiceNumber||'').trim()).filter(Boolean));
 let nextInvoiceNo=Math.max(0,...[...usedInvoiceNumbers].map(v=>{const m=v.match(/^SKM-(\d+)$/);return m?Number(m[1])||0:0}))+1;
 let invoiceNumber='SKM-'+String(nextInvoiceNo).padStart(3,'0');
 while(usedInvoiceNumbers.has(invoiceNumber)){nextInvoiceNo++;invoiceNumber='SKM-'+String(nextInvoiceNo).padStart(3,'0');}
 const bill={id:'B'+Date.now()+Math.random().toString(36).slice(2,6),invoiceNumber,customerName,mobile,doctor,paymentMode,note,items,...totals,billDate:today(),sourceOrderId:sourceOrderId||'',createdAt:new Date().toISOString(),syncStatus:'Local'};
 const sourceOrder=sourceOrderId?currentOrders.find(x=>x.id===sourceOrderId):null;
 const stockAlreadyReserved=!!(configured&&sourceOrder&&orderHasStockReservation(sourceOrder)&&!sourceOrder.stockRestored); // Local-safe mode never trusts legacy online reservations.
 bill.stockAlreadyReserved=stockAlreadyReserved;
 if(saveBtn){saveBtn.dataset.saving='1';saveBtn.disabled=true;saveBtn.setAttribute('aria-busy','true');saveBtn.textContent='⏳ Saving Bill...';}
 try{
  // Validate every line against the exact selected batch before changing anything.
  for(const it of items){
   const b=batches.find(x=>String(x.id)===String(it.batchId)),p=products.find(x=>String(x.id)===String(it.productId));
   if(!b||!p)throw Error('Selected medicine/batch is no longer available. Refresh and add it again.');
   if(expiryStatus(b)==='EXPIRED')throw Error('Expired batch cannot be billed: '+(b.batchNumber||it.batchNumber||it.name));
   if(!stockAlreadyReserved && Number(b.stock||0)<Number(it.qty||0))throw Error('Insufficient stock in batch '+(b.batchNumber||it.batchNumber||it.name)+'. Available: '+Number(b.stock||0));
  }
  if(!stockAlreadyReserved){
   for(const it of items){const b=batches.find(x=>String(x.id)===String(it.batchId));b.stock=Math.max(0,Number(b.stock||0)-Number(it.qty||0));}
   const touched=[...new Set(items.map(it=>String(it.productId)))];
   for(const pid of touched){const p=products.find(x=>String(x.id)===pid);if(p)p.stock=batches.filter(x=>String(x.productId)===pid).reduce((n,x)=>n+Math.max(0,Number(x.stock||0)),0);}
  }
  // Persist the complete local bill transaction before any UI refresh.
  bills.unshift(bill);set('bills',bills);set('batches',batches);set('products',products);
  const sm=get('stockMovements',[]);sm.push(...items.map((it,i)=>({id:bill.id+'_SM'+i,type:'SALE',productId:it.productId,batchId:it.batchId,batchNumber:it.batchNumber,qty:-Number(it.qty||0),reference:invoiceNumber,createdAt:new Date().toISOString()})));set('stockMovements',sm);
  if(mobile){customers=customers.filter(c=>String(c.mobile||'')!==String(mobile));customers.push({name:customerName,mobile,lastDoctor:doctor,lastPurchaseDate:today(),lastBillNumber:invoiceNumber});set('customers',customers)}
  setPendingBills([...getPendingBills(),bill]);
  // Clear the cart only after all local writes have succeeded.
  billCart=[];sourceOrderId='';['bCustomer','bMobile','bDoctor','bNote'].forEach(id=>{if($(id))$(id).value=''});if($('bDiscount'))$('bDiscount').value=0;if($('bGst'))$('bGst').value=0;window.setDiscountType?.('flat');
  renderAll();
  schedulePendingBillSync();
  alert('Bill saved: '+invoiceNumber+'\nSaved safely on this phone.');
  window.showBillActions?.(bill);
 }catch(e){
  console.error('Could not save bill:',e);
  alert('Could not save bill: '+(e?.message||String(e)));
 }finally{
  if(saveBtn){saveBtn.disabled=false;saveBtn.removeAttribute('aria-busy');saveBtn.removeAttribute('data-saving');saveBtn.textContent='💾 Save Bill';}
 }
};

