window.itemManufacturer=function(i){const direct=i?.manufacturer||i?.manufacturerDetails||i?.maker||i?.makerName||'';if(direct)return direct;const p=products.find(x=>x.id===i?.productId)||{};const b=batches.find(x=>x.id===i?.batchId)||{};return p.manufacturer||p.manufacturerDetails||p.maker||p.makerName||b.manufacturer||b.manufacturerDetails||b.maker||b.makerName||''};const itemManufacturer=window.itemManufacturer;
function buildInvoiceHtml(b,assets){const rows=(b.items||[]).map((i,n)=>'<tr><td class="c">'+(n+1)+'</td><td>'+esc(i.name||i.productName||'-')+'</td><td>'+esc(window.itemManufacturer(i)||'-')+'</td><td>'+esc(i.batchNumber||'-')+'</td><td class="c">'+Number(i.qty||0)+'</td><td class="r">'+money(i.price)+'</td><td class="r">'+money(Number(i.qty||0)*Number(i.price||0))+'</td></tr>').join('');return '<!doctype html><html><head><meta charset="utf-8"><title>'+esc(b.invoiceNumber)+'</title>'+invoiceCss()+'</head><body><div class="invoicePage"><div class="invHeader"><div class="invBrand"><img src="'+assets.topLogo+'" class="invTopLogo"><div><div class="invShop">Sri Krishna Medicals</div><div>Kaveri Road, Pennagaram,<br>Dharmapuri District, Tamil Nadu - 636 810</div><div>Phone: <b>8300363317</b></div><div>Drug Licence No: TN/DPI/01386/2021</div><div>FSSAI Licence No: 22422039000512</div></div></div><div class="invMeta"><div class="invNo">Invoice '+esc(b.invoiceNumber)+'</div><div class="metaGrid"><b>Date</b><span>'+esc(b.billDate||'-')+'</span><b>Customer</b><span>'+esc(b.customerName||'Walk-in Customer')+'</span><b>Mobile</b><span>'+esc(b.mobile||'-')+'</span><b>Prescribed By</b><span>'+esc(b.doctor||'-')+'</span></div></div></div><table class="items"><thead><tr><th>S.No</th><th>Medicine</th><th>Manufacturer</th><th>Batch</th><th>Qty</th><th>Rate (₹)</th><th>Amount (₹)</th></tr></thead><tbody>'+rows+'</tbody></table><div class="bottomRow"><div class="totals"><div><b>Subtotal</b> : '+money(b.subtotal)+'</div><div><b>Discount</b> : '+money(b.discount)+'</div><div><b>GST</b> : '+money(b.gst)+'</div><div class="grand"><b>Grand Total</b> : '+money(b.grandTotal)+'</div><div class="pay"><b>Payment Mode</b> : '+esc(b.paymentMode||'-')+'<br><span class="note"><b>Note</b> : '+esc(b.note||'-')+'</span></div></div><div class="sig"><img src="'+assets.signature+'" alt="Pharmacist Signature"><div class="sigline"></div><div class="siglabel">Pharmacist Signature</div></div></div><div class="footer"><div class="footerText"><span class="thanks">Thank you for purchasing</span><span>|</span><span>Order through WhatsApp by using <b class="wa">SKMedKART app</b></span></div><img src="'+assets.footerLogo+'" class="footerLogo" alt="SKMedKART"></div></div></body></html>'}
async function billHtml(b){const assets=await invoiceAssets();return buildInvoiceHtml(b,assets)}
window.printBill=async id=>{const b=typeof id==='object'?id:findBill(id);if(!b)return alert('Bill not found.');const html=await billHtml(b);let frame=document.getElementById('printFrame');if(frame)frame.remove();frame=document.createElement('iframe');frame.id='printFrame';frame.style.position='fixed';frame.style.width='1px';frame.style.height='1px';frame.style.border='0';frame.style.opacity='0';document.body.appendChild(frame);const docx=frame.contentDocument||frame.contentWindow.document;docx.open();docx.write(html);docx.close();frame.onload=()=>setTimeout(()=>{try{frame.contentWindow.focus();frame.contentWindow.print()}catch(e){const w=window.open('','_blank');if(!w)return alert('Please allow popups for printing.');w.document.write(html);w.document.close();w.focus();setTimeout(()=>w.print(),300)}},200)};
async function pdfBlob(b){
  const assets=await invoiceAssets();
  const W=1240,H=1754;
  const canvas=document.createElement('canvas'); canvas.width=W; canvas.height=H;
  const ctx=canvas.getContext('2d');
  ctx.fillStyle='#fff'; ctx.fillRect(0,0,W,H);
  const img=src=>new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=()=>rej(new Error('Could not load invoice image'));im.src=src});
  const [topLogo,footerLogo,signature]=await Promise.all([img(assets.topLogo),img(assets.footerLogo),img(assets.signature)]);
  const money2=v=>'₹'+Number(v||0).toFixed(2);
  const esc2=v=>String(v??'');
  const fit=(im,x,y,w,h)=>{const r=Math.min(w/im.naturalWidth,h/im.naturalHeight);const dw=im.naturalWidth*r,dh=im.naturalHeight*r;ctx.drawImage(im,x+(w-dw)/2,y+(h-dh)/2,dw,dh)};
  ctx.strokeStyle='#0b5aa6';ctx.lineWidth=2;ctx.strokeRect(10,10,W-20,H-20);
  fit(topLogo,35,35,185,185);
  ctx.fillStyle='#123f7c';ctx.font='700 38px Arial';ctx.fillText('Sri Krishna Medicals',230,78);
  ctx.fillStyle='#222';ctx.font='20px Arial';
  ctx.fillText('Kaveri Road, Pennagaram, Dharmapuri District,',230,112);
  ctx.fillText('Tamil Nadu - 636 810',230,132);
  ctx.fillText('Phone: 8300363317',230,152);
  ctx.fillText('Drug Licence No: TN/DPI/01386/2021',230,177);
  ctx.fillText('FSSAI Licence No: 22422039000512',230,202);
  ctx.fillStyle='#dff0ff';ctx.fillRect(865,42,330,58);
  ctx.fillStyle='#123f7c';ctx.font='700 28px Arial';ctx.fillText('Invoice '+esc2(b.invoiceNumber||'-'),885,80);
  ctx.fillStyle='#222';ctx.font='18px Arial';
  const meta=[['Date',b.billDate||'-'],['Customer',b.customerName||'Walk-in Customer'],['Mobile',b.mobile||'-'],['Prescribed By',b.doctor||'-']];
  // Keep the label and value in separate columns so long customer/doctor names never overlap.
  meta.forEach((m,i)=>{
    const yy=125+i*30;
    ctx.font='700 18px Arial';ctx.fillText(m[0],865,yy);
    ctx.font='18px Arial';ctx.fillText(': '+esc2(m[1]),985,yy);
  });
  ctx.strokeStyle='#1b5f9f';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(35,230);ctx.lineTo(1205,230);ctx.stroke();
  const x=[35,105,420,600,790,855,1000,1205], top=250, headH=42, rowH=48;
  ctx.fillStyle='#dff0ff';ctx.fillRect(x[0],top,x[7]-x[0],headH);
  ctx.strokeStyle='#333';ctx.lineWidth=1;ctx.strokeRect(x[0],top,x[7]-x[0],headH);
  ['S.No','Medicine','Manufacturer','Batch','Qty','Rate (₹)','Amount (₹)'].forEach((h,i)=>{ctx.fillStyle='#123f7c';ctx.font='700 16px Arial';ctx.fillText(h,x[i]+8,top+27);});
  let yy=top+headH;
  (b.items||[]).forEach((it,n)=>{
    ctx.strokeStyle='#333';ctx.strokeRect(x[0],yy,x[7]-x[0],rowH);
    for(let j=1;j<x.length-1;j++){ctx.beginPath();ctx.moveTo(x[j],yy);ctx.lineTo(x[j],yy+rowH);ctx.stroke();}
    const man=window.itemManufacturer?window.itemManufacturer(it):((it.manufacturer||it.manufacturerDetails)||'-');
    const vals=[String(n+1),esc2(it.name||it.productName||'-'),esc2(man||'-'),esc2(it.batchNumber||'-'),String(it.qty||0),Number(it.price||0).toFixed(2),Number((it.qty||0)*(it.price||0)).toFixed(2)];
    vals.forEach((v,j)=>{ctx.fillStyle='#222';ctx.font='16px Arial';ctx.fillText(v.slice(0,j===1?34:20),x[j]+8,yy+29);});
    yy+=rowH;
  });
  const totalY=Math.min(Math.max(yy+45,760),1300);
  ctx.fillStyle='#222';ctx.font='700 20px Arial';ctx.fillText('Subtotal',50,totalY);ctx.font='20px Arial';ctx.fillText(': '+money2(b.subtotal),205,totalY);
  ctx.font='700 20px Arial';ctx.fillText('Discount',50,totalY+34);ctx.font='20px Arial';ctx.fillText(': '+money2(b.discount),205,totalY+34);
  ctx.font='700 20px Arial';ctx.fillText('GST',50,totalY+68);ctx.font='20px Arial';ctx.fillText(': '+money2(b.gst),205,totalY+68);
  ctx.fillStyle='#dff0ff';ctx.fillRect(35,totalY+90,500,50);ctx.fillStyle='#123f7c';ctx.font='700 26px Arial';ctx.fillText('Grand Total : '+money2(b.grandTotal),50,totalY+124);
  ctx.fillStyle='#222';ctx.font='700 20px Arial';ctx.fillText('Payment Mode :',50,totalY+172);ctx.font='20px Arial';ctx.fillText(esc2(b.paymentMode||'-'),215,totalY+172);
  ctx.font='700 20px Arial';ctx.fillText('Note :',50,totalY+206);ctx.font='20px Arial';ctx.fillText(esc2(b.note||'-'),120,totalY+206);
  fit(signature,860,totalY+125,300,125);
  ctx.strokeStyle='#333';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(850,totalY+255);ctx.lineTo(1190,totalY+255);ctx.stroke();
  ctx.fillStyle='#222';ctx.font='18px Arial';ctx.fillText('Pharmacist Signature',955,totalY+282);
  const footerY=H-90;
  ctx.fillStyle='#0b4f91';ctx.fillRect(10,footerY,W-20,72);
  fit(footerLogo,955,footerY+5,235,62);
  ctx.fillStyle='#fff';ctx.font='16px Arial';ctx.fillText('Thank you for purchasing  |  Order through WhatsApp by using SKMedKART app',40,footerY+30);
  const raw=atob(canvas.toDataURL('image/jpeg',0.92).split(',')[1]);
  const u=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)u[i]=raw.charCodeAt(i);
  const enc=new TextEncoder(),B=x=>enc.encode(String(x));
  const imgObj=B('<< /Type /XObject /Subtype /Image /Width '+W+' /Height '+H+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+u.length+' >>\nstream\n');
  const content=B('q 595 0 0 842 0 0 cm /Im1 Do Q');
  const objs={};
  objs[1]=B('<< /Type /Catalog /Pages 2 0 R >>');
  objs[2]=B('<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
  objs[3]=B('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /Im1 4 0 R >> >> /Contents 5 0 R >>');
  objs[4]=imgObj;objs[5]=B('<< /Length '+content.length+' >>\nstream\n');
  const chunks=[B('%PDF-1.4\n')],offs=new Array(6).fill(0);let pos=chunks[0].length;
  const add=(n,parts)=>{offs[n]=pos;const all=[B(n+' 0 obj\n'),...parts,B('\nendobj\n')];chunks.push(...all);pos+=all.reduce((a,z)=>a+z.length,0)};
  add(1,[objs[1]]);add(2,[objs[2]]);add(3,[objs[3]]);add(4,[objs[4],u,B('\nendstream')]);add(5,[objs[5],content,B('\nendstream')]);
  const xref=pos;let xrefStr='xref\n0 6\n0000000000 65535 f \n';for(let n=1;n<=5;n++)xrefStr+=String(offs[n]).padStart(10,'0')+' 00000 n \n';xrefStr+='trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';chunks.push(B(xrefStr));
  return new Blob(chunks,{type:'application/pdf'});
}
window.saveBillPdf=async id=>{const b=findBill(id);if(!b)return;try{const blob=await pdfBlob(b);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=b.invoiceNumber+'.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){alert('Could not create PDF: '+e.message)}};
window.shareBill=async id=>{const b=findBill(id);if(!b)return;const text='Sri Krishna Medicals, Pennagaram\nInvoice: '+b.invoiceNumber+'\nCustomer: '+b.customerName+'\nTotal: '+money(b.grandTotal)+'\nPayment: '+b.paymentMode;if(navigator.share){try{const file=new File([await pdfBlob(b)],b.invoiceNumber+'.pdf',{type:'application/pdf'});if(navigator.canShare?.({files:[file]}))await navigator.share({title:'Medical Bill '+b.invoiceNumber,text,files:[file]});else await navigator.share({title:'Medical Bill '+b.invoiceNumber,text});return}catch(e){if(e.name==='AbortError')return}}navigator.clipboard?.writeText(text);alert('Bill details copied. You can paste and send to the customer. Use Save PDF to attach the invoice.')};
function billViewHtml(b){const returned=b.returned?'<div class="returnInfo">↩ This bill was returned on '+esc(b.returnedAtText||b.returnedAt||b.billDate||'')+'. Stock has been restored.</div>':'';const shop='<div class="card shopBillHeader" style="padding:14px;margin:10px 0;text-align:center"><b style="font-size:20px">Sri Krishna Medicals</b><br><span>Kaveri Road, Pennagaram, Dharmapuri District, Tamil Nadu</span><br><span>📞 8300363317</span><br><span><b>Drug Licence No:</b> TN/DPI/01386/20,21</span><br><span><b>FSSAI Licence No:</b> 22422039000512</span></div>';return '<h2>📄 Invoice '+esc(b.invoiceNumber)+'</h2>'+returned+'<p class="small">'+esc(b.billDate||'')+' • '+esc(b.paymentMode||'')+'</p>'+shop+'<div class="card" style="padding:14px;margin:10px 0"><b>Customer:</b> '+esc(b.customerName||'Walk-in Customer')+'<br><b>Mobile:</b> '+esc(b.mobile||'-')+'<br><b>Prescribed by:</b> '+esc(b.doctor||'-')+'</div><table class="viewBillTable"><thead><tr><th>Medicine</th><th>Manufacturer</th><th>Batch</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody>'+((b.items||[]).map(i=>'<tr><td>'+esc(i.name||i.productName||'-')+'</td><td>'+esc(window.itemManufacturer(i)||'-')+'</td><td>'+esc(i.batchNumber||'-')+'</td><td>'+Number(i.qty||0)+'</td><td>'+money(i.price)+'</td><td>'+money(Number(i.qty||0)*Number(i.price||0))+'</td></tr>').join(''))+'</tbody></table><div class="modalTotals"><div class="totalLine"><span>Subtotal</span><b>'+money(b.subtotal)+'</b></div><div class="totalLine"><span>Discount</span><b>-'+money(b.discount)+'</b></div><div class="totalLine"><span>GST</span><b>'+money(b.gst)+'</b></div><div class="totalLine grand"><span>Grand Total</span><span>'+money(b.grandTotal)+'</span></div></div><div style="text-align:right;margin:18px 10px 4px"><img src="data:image/jpeg;base64," alt="Pharmacist Signature" style="width:170px;height:auto;display:inline-block"><div style="border-top:1px solid #333;width:190px;margin-left:auto;margin-top:-2px"></div><div style="width:190px;margin-left:auto;text-align:center;font-size:12px;margin-top:3px">Pharmacist Signature</div></div><div class="modalActions"><button onclick="printBill(\''+esc(b.id||b.invoiceNumber)+'\')">🖨 Print</button><button class="secondary" onclick="saveBillPdf(\''+esc(b.id||b.invoiceNumber)+'\')">📄 Save PDF</button><button class="ok" onclick="shareBill(\''+esc(b.id||b.invoiceNumber)+'\')">📤 Share</button>'+(!b.returned?'<button class="danger" onclick="returnBill(\''+esc(b.id||b.invoiceNumber)+'\')">↩ Return Bill</button>':'<button class="danger" onclick="deleteBillRecord(\''+esc(b.id||b.invoiceNumber)+'\')">🗑 Delete Record</button>')+'</div>'}
window.viewBill=id=>{const b=findBill(id);if(!b)return alert('Bill not found.');$('billModalContent').innerHTML=billViewHtml(b);const shareBtn=$('billModalContent')?.querySelector('[data-share-bill]');if(shareBtn)shareBtn.onclick=()=>window.shareBill(b.id||b.invoiceNumber);$('billModal').classList.remove('hidden')};window.closeBillView=()=>$('billModal').classList.add('hidden');$('billModal')?.addEventListener('click',e=>{if(e.target===$('billModal'))closeBillView()});
window.renderBillHistory=()=>{const el=$('billHistoryList');if(!el)return;const q=String($('billHistorySearch')?.value||'').trim().toLowerCase();const rows=bills.filter(b=>!q||[b.invoiceNumber,b.customerName,b.mobile].join(' ').toLowerCase().includes(q)).sort((a,b)=>{const na=Number(String(a.invoiceNumber||'').match(/^(?:SKM-)?(\d+)$/)?.[1]||-1),nb=Number(String(b.invoiceNumber||'').match(/^(?:SKM-)?(\d+)$/)?.[1]||-1);return nb-na||t(b.createdAt||b.billDate)-t(a.createdAt||a.billDate)});el.innerHTML=rows.map(b=>{const id=esc(b.id||b.invoiceNumber);return '<div class="billHistoryRow"><div class="billHistoryTop"><div><b style="font-size:20px">'+esc(b.invoiceNumber)+'</b><div class="small">'+esc(b.billDate||'')+' • '+esc(b.customerName||'Walk-in Customer')+'</div>'+ (b.returned?'<span class="returnedBadge">↩ Returned</span>':'')+'</div><div class="amount">'+money(b.grandTotal)+'</div></div><div class="actions"><button onclick="viewBill(\''+id+'\')">👁 View</button><button class="secondary" onclick="printBill(\''+id+'\')">🖨 Print</button>'+(!b.returned?'<button class="danger" onclick="returnBill(\''+id+'\')">↩ Return</button>':'<button class="danger" onclick="deleteBillRecord(\''+id+'\')">🗑 Delete Record</button>')+'</div></div>'}).join('')||'<div class="small">No bills found.</div>'};
window.returnBill=async id=>{const b=findBill(id);if(!b)return alert('Bill not found.');if(b.returned)return alert('This bill has already been returned.');if(!confirm('Return bill '+b.invoiceNumber+'? This will restore all item quantities back to stock.'))return;try{if(configured){await runTransaction(db,async tx=>{const refs=[];for(const it of b.items||[]){refs.push(doc(db,'batches',it.batchId));refs.push(doc(db,'products',it.productId))}const uniq=[...new Map(refs.map(r=>[r.path,r])).values()];const snaps=await Promise.all(uniq.map(r=>tx.get(r)));const map=new Map(uniq.map((r,i)=>[r.path,snaps[i]]));for(const it of b.items||[]){const br=doc(db,'batches',it.batchId),pr=doc(db,'products',it.productId),bs=map.get(br.path),ps=map.get(pr.path);if(!bs?.exists()||!ps?.exists())throw Error('Original product or batch not found for '+(it.name||it.batchNumber));tx.update(br,{stock:Number(bs.data().stock||0)+Number(it.qty||0),updatedAt:serverTimestamp()});tx.update(pr,{stock:Number(ps.data().stock||0)+Number(it.qty||0),updatedAt:serverTimestamp()});tx.set(doc(collection(db,'stockMovements')),{type:'RETURN',productId:it.productId,batchId:it.batchId,batchNumber:it.batchNumber,qty:Number(it.qty||0),reference:b.invoiceNumber,createdAt:serverTimestamp()})}tx.update(doc(db,'bills',b.id),{returned:true,returnedAt:serverTimestamp(),returnedAtText:new Date().toLocaleString('en-IN'),returnReason:'Bill return - stock restored'})})}else{for(const it of b.items||[]){const batch=batches.find(x=>x.id===it.batchId),prod=products.find(x=>x.id===it.productId);if(!batch||!prod)throw Error('Original product or batch not found for '+(it.name||it.batchNumber));batch.stock=Math.max(0,Number(batch.stock||0)+Number(it.qty||0));}for(const pid of [...new Set((b.items||[]).map(it=>String(it.productId)))]){const prod=products.find(x=>String(x.id)===pid);if(prod)prod.stock=batches.filter(x=>String(x.productId)===pid).reduce((n,x)=>n+Math.max(0,Number(x.stock||0)),0);}b.returned=true;b.returnedAt=new Date().toISOString();b.returnedAtText=new Date().toLocaleString('en-IN');b.returnReason='Bill return - stock restored';set('batches',batches);set('products',products);set('bills',bills);const sm=get('stockMovements',[]);for(const it of b.items||[])sm.push({id:'RT'+Date.now()+Math.random(),type:'RETURN',productId:it.productId,batchId:it.batchId,batchNumber:it.batchNumber,qty:Number(it.qty||0),reference:b.invoiceNumber,createdAt:new Date().toISOString()});set('stockMovements',sm)}alert('Bill returned successfully. Stock has been restored.');closeBillView();renderAll()}catch(e){alert('Return failed: '+e.message)}};


window.deleteBillRecord=async id=>{
 const b=findBill(id);
 if(!b)return alert('Bill not found.');
 if(!b.returned)return alert('For stock safety, first use Return Bill. After stock is restored, you can permanently delete the returned bill record.');
 if(!confirm('Permanently delete returned bill record '+b.invoiceNumber+'? This cannot be undone.'))return;
 try{
   if(configured){
     await deleteDoc(doc(db,'bills',b.id));
   }else{
     bills=bills.filter(x=>(x.id||x.invoiceNumber)!==id);
     set('bills',bills);
   }
   alert('Returned bill record deleted permanently.');
   closeBillView();
   renderAll();
 }catch(e){alert('Could not delete bill record: '+e.message)}
};

function billRow(b,compact=false){const id=esc(b.id||b.invoiceNumber),returned=b.returned?'<span class="returnedBadge">↩ Returned</span>':'';return '<div class="itemrow"><b>'+esc(b.invoiceNumber)+'</b> • '+esc(b.customerName||'Walk-in')+' <span class="right">'+money(b.grandTotal)+'</span><div class="small">'+esc(b.billDate||'')+' • '+esc(b.paymentMode||'')+'</div>'+returned+'<div class="actions"><button onclick="viewBill(\''+id+'\')">👁 View</button><button onclick="printBill(\''+id+'\')">🖨 Print</button><button class="secondary" onclick="saveBillPdf(\''+id+'\')">📄 Save PDF</button>'+(!b.returned?'<button class="danger" onclick="returnBill(\''+id+'\')">↩ Return</button>':'')+'<button class="ok" onclick="shareBill(\''+id+'\')">📤 Share</button></div></div>'}
window.showBillActions=b=>{setTimeout(()=>{alert('Bill saved successfully. You can now Print, Save PDF or Share it from Recent Bills.')},100)};
window.saveSupplier=async()=>{const name=$('sName').value.trim(),mobile=$('sMobile').value.trim(),address=$('sAddress').value.trim(),gst=$('sGst').value.trim();if(!name)return alert('Enter supplier/company name.');try{if(configured){const id=String(name).toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')||uid();await setDoc(doc(db,'suppliers',id),{name,mobile,address,gst,updatedAt:serverTimestamp(),createdAt:serverTimestamp()},{merge:true})}else{const i=suppliers.findIndex(x=>x.name.toLowerCase()===name.toLowerCase());const local={id:'S'+Date.now(),name,mobile,address,gst};if(i>=0)suppliers[i]=local;else suppliers.unshift(local);set('suppliers',suppliers)}alert('Supplier saved.');['sName','sMobile','sAddress','sGst'].forEach(id=>$(id).value='');renderAll()}catch(e){alert('Could not save supplier: '+e.message)}};function renderSuppliers(){const el=$('supplierList');if(!el)return;el.innerHTML=suppliers.map(x=>'<div class="itemrow"><b>'+esc(x.name)+'</b><br><span class="small">'+esc(x.mobile||'')+(x.address?' • '+esc(x.address):'')+(x.gst?' • GST: '+esc(x.gst):'')+'</span></div>').join('')||'<div class="small">No suppliers saved yet.</div>'}
const backupCollections=['products','batches','bills','purchases','suppliers','customers','reminders','orders','stockMovements'];
async function backupData(){
 const out={app:'SKMedKART Admin Portal',version:'5.6',createdAt:new Date().toISOString(),mode:configured?'firebase':'demo',collections:{}};
 if(configured){for(const name of backupCollections){const snap=await getDocs(collection(db,name));out.collections[name]=snap.docs.map(d=>({id:d.id,...d.data()}));}}
 else {const map={products,currentOrders,purchases,batches,bills,customers,reminders,suppliers,stockMovements:get('stockMovements',[])};for(const name of backupCollections){const key=name==='orders'?'currentOrders':name;out.collections[name]=map[key]||[];}}
 return out;
}
window.downloadBackup=async()=>{try{const status=$('restoreStatus');if(status)status.textContent='Preparing backup...';const data=await backupData();const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='SKMedKART_BACKUP_'+today()+'_'+Date.now()+'.json';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);if(status)status.textContent='Backup downloaded successfully.';}catch(e){alert('Backup failed: '+e.message)}};
async function restoreData(data){
 if(!data?.collections||typeof data.collections!=='object')throw Error('Invalid SKMedKART backup file.');
 if(configured){
  for(const name of backupCollections){const rows=Array.isArray(data.collections[name])?data.collections[name]:[];for(let i=0;i<rows.length;i+=400){const wb=writeBatch(db);rows.slice(i,i+400).forEach(row=>{const copy={...row};const id=String(copy.id||uid());delete copy.id;wb.set(doc(db,name,id),copy,{merge:true});});await wb.commit();}}
 }else{
  // Restore is a snapshot: the selected backup is loaded exactly as saved. We do
  // not subtract "duplicate" purchases from the snapshot, because that can turn a
  // correct batch quantity into an incorrect one. The stock-integrity reconciliation
  // below handles legacy missing movement/batch links without double-adding stock.
  for(const name of backupCollections){const rows=Array.isArray(data.collections[name])?data.collections[name]:[];set(name,rows)}
  products=get('products',[]);currentOrders=get('orders',[]);purchases=get('purchases',[]);batches=get('batches',[]);bills=get('bills',[]);customers=get('customers',[]);reminders=loadLocalReminders();suppliers=get('suppliers',[]);
  repairLocalStockConsistency();
  localStorage.setItem('skm_stock_repair_v5_done','yes');
 }
}
$('restoreFile')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;const status=$('restoreStatus');try{if(!confirm('Restore this backup? Existing matching records will be overwritten or updated.')){e.target.value='';return}if(status)status.textContent='Restoring backup...';const data=JSON.parse(await file.text());await restoreData(data);if(status)status.textContent='Restore completed successfully.';if(!configured){liveStarted=false;await loadAll()}else alert('Restore completed. Live data will refresh automatically.');}catch(err){if(status)status.textContent='Restore failed.';alert('Restore failed: '+err.message)}finally{e.target.value=''}});

window.calculatePurchaseGst=()=>{
  const base=Math.max(0,Number($('puCost')?.value)||0);
  const rate=Math.max(0,Number($('puGst')?.value)||0);
  const total=base+(base*rate/100);
  if($('puCostWithGst'))$('puCostWithGst').value=total.toFixed(2);
  return {base,rate,total};
};
['puCost','puGst'].forEach(id=>$(id)?.addEventListener('input',window.calculatePurchaseGst));
const PENDING_PURCHASES_KEY='skm_local_pending_purchases_v2';
function getPendingPurchases(){return get(PENDING_PURCHASES_KEY,[])}
function setPendingPurchases(v){set(PENDING_PURCHASES_KEY,v)}
function mergePendingPurchases(remote){const map=new Map((remote||[]).map(x=>[String(x.id||''),x]));for(const x of getPendingPurchases()){const k=String(x.id||'');if(k&&!map.has(k))map.set(k,{...x,syncStatus:'Pending Firebase sync'})}return [...map.values()].sort((a,b)=>t(b.createdAt||b.purchaseDate)-t(a.createdAt||a.purchaseDate))}
let pendingPurchaseSyncTimer=null,pendingPurchaseSyncRunning=false;
async function syncPendingPurchases(){
 if(!configured||!db||pendingPurchaseSyncRunning)return;
 const pending=getPendingPurchases();if(!pending.length)return;
 pendingPurchaseSyncRunning=true;
 try{
  const remaining=[];
  for(const purchase of pending){
   try{
    const productId=purchase.productId,bid=productId+'__'+purchase.batchNumber;
    await runTransaction(db,async tx=>{
      const purRef=doc(db,'purchases',purchase.id),pr=doc(db,'products',productId),br=doc(db,'batches',bid);
      const [purSnap,ps,bs]=await Promise.all([tx.get(purRef),tx.get(pr),tx.get(br)]);
      if(purSnap.exists())return;
      const existingProduct=ps.exists()?ps.data():{};
      const old=bs.exists()?bs.data():{};
      tx.set(br,{...old,id:bid,productId,productName:purchase.productName,category:purchase.category,cat:purchase.category,schedule:purchase.schedule,manufacturer:purchase.manufacturer,manufacturerDetails:purchase.manufacturerDetails,batchNumber:purchase.batchNumber,expiryDate:purchase.expiryDate,stock:Number(old.stock||0)+Number(purchase.qty||0),purchasePrice:Number(purchase.purchasePrice||0),purchaseGstRate:Number(purchase.purchaseGstRate||0),purchasePriceWithGst:Number(purchase.purchasePriceWithGst||0),mrp:Number(purchase.mrp||0),sellingPrice:Number(purchase.sellingPrice||0),updatedAt:serverTimestamp(),createdAt:old.createdAt||serverTimestamp()},{merge:true});
      tx.set(pr,{...existingProduct,id:productId,name:purchase.productName,cat:purchase.category,category:purchase.category,schedule:purchase.schedule,manufacturer:purchase.manufacturer||existingProduct.manufacturer||'',manufacturerDetails:purchase.manufacturerDetails||existingProduct.manufacturerDetails||'',price:Number(purchase.sellingPrice||existingProduct.price||0),stock:Number(existingProduct.stock||0)+Number(purchase.qty||0),lowStockLevel:Number(purchase.minQty||existingProduct.lowStockLevel||0),purchasePrice:Number(purchase.purchasePrice||0),purchaseGstRate:Number(purchase.purchaseGstRate||0),purchasePriceWithGst:Number(purchase.purchasePriceWithGst||0),mrp:Number(purchase.mrp||0),gst:Number(purchase.purchaseGstRate||0),active:true,updatedAt:serverTimestamp(),createdAt:existingProduct.createdAt||serverTimestamp()},{merge:true});
      tx.set(purRef,{...purchase,createdAt:purchase.createdAt||serverTimestamp()},{merge:true});
      tx.set(doc(db,'stockMovements',purchase.id+'_SM'),{type:'PURCHASE',productId,batchId:bid,batchNumber:purchase.batchNumber,qty:Number(purchase.qty||0),reference:purchase.invoice||'PURCHASE',purchasePriceWithGst:Number(purchase.purchasePriceWithGst||0),createdAt:serverTimestamp()},{merge:true});
    });
   }catch(err){remaining.push(purchase);console.warn('Pending purchase sync failed:',err)}
  }
  setPendingPurchases(remaining);
  if(configured){const n=$('notice');if(n)n.innerHTML=remaining.length?'<b>☁️ Online + Billing Safe mode</b><br><span class="small">'+remaining.length+' purchase(s) saved safely on this phone and waiting for Firebase sync. Purchase entry remains available.</span>':'<b>☁️ Online + Billing Safe mode</b><br><span class="small">Firebase sync is active. Bills and purchases are saved on this phone first and synced automatically.</span>';}
 }finally{pendingPurchaseSyncRunning=false;renderAll()}
}
function schedulePendingPurchaseSync(){clearTimeout(pendingPurchaseSyncTimer);pendingPurchaseSyncTimer=setTimeout(()=>syncPendingPurchases().catch(console.error),1200)}
window.addEventListener('online',schedulePendingPurchaseSync);
setInterval(()=>{if(navigator.onLine)syncPendingPurchases().catch(console.error)},60000);

